const output = toBlob(doc);

// draw some text
doc.fontSize(25).text('Here is some vector graphics...', 100, 80);

// draw vector graphics
doc
  .save()
  .moveTo(100, 150)
  .lineTo(100, 250)
  .lineTo(200, 250)
  .fill('#FF3300');

doc.circle(280, 200, 50).fill('#6600FF');

// draw an SVG path
doc
  .scale(0.6)
  .translate(470, 130)
  .path('M 250,75 L 323,301 131,161 369,161 177,301 z')
  .fill('red', 'even-odd')
  .restore();

doc.save();

// fill with a gradient
const gradient = doc
  .linearGradient(100, 300, 200, 300)
  .stop(0, 'green')
  .stop(0.5, 'red')
  .stop(1, 'green');
doc.rect(100, 300, 100, 100).fill(gradient);

// fill and stroke with an uncolored tiling pattern
const stripe45d = doc.pattern(
  [1, 1, 4, 4],
  3,
  3,
  '1 w 0 1 m 4 5 l s 2 0 m 5 3 l s'
);
doc.circle(280, 350, 50).fill([stripe45d, 'blue']);

doc
  .rect(380, 300, 100, 100)
  .fillColor('lime')
  .strokeColor([stripe45d, 'orange'])
  .lineWidth(5)
  .fillAndStroke();
doc.restore();

